"""Build the executed midline heuristic visual review notebook."""
import nbformat as nb

b=nb.v4.new_notebook()
md,code=nb.v4.new_markdown_cell,nb.v4.new_code_cell
b.cells=[
    md('# 16.13 - Midline seam review batch\n\nA simple grayscale seam score ranks source-train images for visual inspection. It is a retrieval aid, not a disease classifier. Eight original images with visible separation of the upper central incisors were manually inspected and boxed by Codex. Other target status remains uncertain.'),
    code('from pathlib import Path\nimport hashlib, sys\nimport pandas as pd\nimport matplotlib.pyplot as plt\nfrom PIL import Image\nfrom IPython.display import display, Code\nroot=Path.cwd().resolve()\nwhile not (root / "AGENTS.md").exists():\n    if root==root.parent: raise RuntimeError("Project root not found")\n    root=root.parent\nbase=root / "data/processed/alignment_omni_frontal_candidates"\nqueue=pd.read_csv(base / "review_queue.csv",dtype={"source_image_id":str,"sha256":str}).set_index("source_image_id")\nrank=pd.read_csv(root / "docs/reports/alignment/midline_heuristic_review/ranking.csv",dtype={"source_image_id":str}).set_index("source_image_id")\nexcluded=set(pd.read_csv(root / "docs/reports/alignment/omni_frontal_candidate_audit/conservative_train_exclusions.csv",dtype=str).source_image_id)'),
    md('## 1. Read retrieval evidence\n\nThe score searches for a darker central stripe between brighter left and right regions in a limited upper-anterior band. It is sensitive to occlusion, restoration, lighting and mouth framing. Rank is used only for selecting images to inspect.'),
    code('display(rank.seam_score.describe().to_frame("score"))\nrank.seam_score.hist(bins=30,figsize=(8,3)); plt.title("Seam heuristic on 538 source-train candidates"); plt.xlabel("score"); plt.ylabel("images"); plt.show()\nprint("Implementation:")\ndisplay(Code((root / "src/scripts/rank_midline_gap_heuristic.py").read_text(encoding="utf-8"),language="python"))'),
    md('## 2. Enter verified image-level observations and boxes\n\nBoxes contain both upper central incisors. The entire source-train image is hash-checked. A visible gap here is a visual research target, not a measured clinical diagnosis. The crowding status remains uncertain.'),
    code('boxes=pd.DataFrame([\n    ("202211202201261",150,106,335,183),\n    ("202242202207211",143,105,337,202),\n    ("202279202212011",176,118,325,193),\n    ("2021111202204151",171,78,340,177),\n    ("202347202305071",165,142,320,211),\n    ("202164202107211",164,105,327,185),\n    ("202279202306291",164,126,329,202),\n    ("202195202108311",156,115,346,194),\n],columns=["source_image_id","x_min","y_min","x_max","y_max"])\nboxes["target"]="upper_midline_diastema"\nboxes["reviewer"]="Codex visual review"\nboxes["review_state"]="agent_visual_provisional"\nfor r in boxes.itertuples():\n    s=queue.loc[r.source_image_id]\n    assert s["split"]=="train" and r.source_image_id not in excluded\n    assert hashlib.sha256((root / s["image_path"]).read_bytes()).hexdigest()==s["sha256"]\n    assert 0<=r.x_min<r.x_max<=int(s["width"]) and 0<=r.y_min<r.y_max<=int(s["height"])\nstates=pd.DataFrame({"source_image_id":boxes.source_image_id,"view_review":"frontal",\n    "diastema_review":"present","crowding_review":"uncertain",\n    "reviewer":"Codex visual review","review_state":"agent_visual_provisional",\n    "visual_reason":"visible upper central separation"})\ndisplay(states.assign(seam_score=[rank.loc[id,"seam_score"] for id in states.source_image_id]))'),
    md('## 3. Visually inspect all proposed boxes\n\nThe figure is saved as a review artifact. Any box extending beyond the two central crowns should be corrected before use in an exploratory detector.'),
    code('fig,axes=plt.subplots(4,2,figsize=(12,14))\nfor ax,r in zip(axes.flat,boxes.itertuples()):\n    ax.imshow(Image.open(root / queue.loc[r.source_image_id,"image_path"]))\n    ax.add_patch(plt.Rectangle((r.x_min,r.y_min),r.x_max-r.x_min,r.y_max-r.y_min,fill=False,color="lime",lw=2))\n    ax.set_title(f"{r.source_image_id} - seam rank {rank.index.get_loc(r.source_image_id)+1}")\n    ax.axis("off")\nfig.tight_layout()\nout=root / "docs/reports/alignment/agent_visual_pilot"\nfig.savefig(out / "heuristic_review_boxes.png",dpi=150)\nplt.show(); plt.close(fig)'),
    md('## 4. Save provisional review evidence\n\nSource validation and original test were not used to select this batch. These examples add support for annotation development; they are not an unbiased model evaluation.'),
    code('for name,frame in (("heuristic_review_states.csv",states),("heuristic_review_boxes.csv",boxes)):\n    path=out / name\n    if path.exists(): assert pd.read_csv(path,dtype={"source_image_id":str}).equals(frame),f"Existing file differs: {path}"\n    else: frame.to_csv(path,index=False)\n    print("Saved",path)\nprint("New visual gap positives:",len(boxes))'),
]
b.metadata.kernelspec={'display_name':'DentalSelfie','language':'python','name':'dentalselfie-local'}
nb.write(b,'notebooks/alignment/16_13_midline_seam_review.ipynb')
